// =====================================================================
// RECURRING PAYMENT DETECTION
//
// Mirrors config/levers.yml -> leak_detection.subscriptions
// Edit these numbers here; levers.yml is the human-readable record of why.
// =====================================================================
const CONFIG = {
  minOccurrences:       3,
  intervalToleranceDays: 4,
  priceRisePct:         10,
  trialProbeMaxGbp:     2.00,
  dormantAfterDays:     95,
  annualValueFloorGbp:  50,
  // Price rises get a LOWER floor than everything else. They are rare and
  // high-signal — a 36% hike that happens to work out at £48/yr should
  // never be invisible just because it sits under the general floor.
  priceRiseFloorGbp:    30,
  ignore: ['council tax', 'mortgage', 'rent'],
};

const DAY_MS = 86400000;
const today = new Date();

const rows = $input.all().map(i => i.json);
if (rows.length === 0) {
  return [{ json: { subscriptions: [], findings: [], note: 'no transactions yet' } }];
}

// ---- group by normalised merchant ----
const byMerchant = new Map();
for (const r of rows) {
  const key = r.merchant_key;
  if (!key || CONFIG.ignore.some(ig => key.includes(ig))) continue;
  if (!byMerchant.has(key)) byMerchant.set(key, []);
  byMerchant.get(key).push({
    date: new Date(r.booked_at),
    amount: Math.abs(parseFloat(r.amount_gbp)),
    description: r.raw_description,
  });
}

const median = arr => {
  if (arr.length === 0) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};

// Map a raw interval onto a real-world billing cycle. Bank posting dates
// drift (weekends, month lengths), so we snap to the nearest known cycle
// rather than trusting the raw median.
function classifyCycle(days) {
  const cycles = [
    { days: 7,   label: 'weekly' },
    { days: 14,  label: 'fortnightly' },
    { days: 30,  label: 'monthly' },
    { days: 91,  label: 'quarterly' },
    { days: 182, label: 'half-yearly' },
    { days: 365, label: 'annual' },
  ];
  let best = null;
  let bestDiff = Infinity;
  for (const c of cycles) {
    // Tolerance scales with cycle length — 4 days out on a weekly charge is
    // a lot, 4 days out on an annual one is nothing.
    const tolerance = Math.max(CONFIG.intervalToleranceDays, c.days * 0.15);
    const diff = Math.abs(days - c.days);
    if (diff <= tolerance && diff < bestDiff) {
      best = c;
      bestDiff = diff;
    }
  }
  return best;
}

const subscriptions = [];
const findings = [];

for (const [key, charges] of byMerchant.entries()) {
  if (charges.length < CONFIG.minOccurrences) continue;

  charges.sort((a, b) => a.date - b.date);

  // ---- interval consistency ----
  const intervals = [];
  for (let i = 1; i < charges.length; i++) {
    intervals.push(Math.round((charges[i].date - charges[i - 1].date) / DAY_MS));
  }
  const medianInterval = median(intervals);
  const cycle = classifyCycle(medianInterval);
  if (!cycle) continue;   // irregular spending, not a subscription

  // At least two thirds of the gaps must match the cycle. This is what
  // separates "Netflix every month" from "Tesco roughly every month".
  const tolerance = Math.max(CONFIG.intervalToleranceDays, cycle.days * 0.15);
  const consistent = intervals.filter(iv => Math.abs(iv - cycle.days) <= tolerance).length;
  if (consistent / intervals.length < 0.66) continue;

  const amounts = charges.map(c => c.amount);
  // Use the median of the LAST THREE charges, not all-time. Robust to a
  // one-off odd charge, but still tracks the current price after a rise —
  // an all-time median understates what you are actually paying now.
  const typical = median(amounts.slice(-3));
  const latest = charges[charges.length - 1];
  const lastCharged = latest.date;
  const daysSinceLast = Math.round((today - lastCharged) / DAY_MS);
  const chargesPerYear = 365 / cycle.days;
  const annualCost = +(typical * chargesPerYear).toFixed(2);

  const displayName = key.replace(/\b\w/g, c => c.toUpperCase());
  const isDormant = daysSinceLast > CONFIG.dormantAfterDays;

  subscriptions.push({
    merchant_key: key,
    display_name: displayName,
    typical_amount_gbp: +typical.toFixed(2),
    interval_days: cycle.days,
    occurrences: charges.length,
    first_seen: charges[0].date.toISOString().slice(0, 10),
    last_charged: lastCharged.toISOString().slice(0, 10),
    annual_cost_gbp: annualCost,
    status: isDormant ? 'dormant' : 'active',
  });

  if (isDormant) continue;   // nothing to alert on; it already stopped

  // ================= FINDING: price rise =================
  // Compare the latest charge against the median of everything before it.
  if (charges.length >= 3) {
    const priorMedian = median(amounts.slice(0, -1));
    if (priorMedian > 0) {
      const risePct = ((latest.amount - priorMedian) / priorMedian) * 100;
      if (risePct >= CONFIG.priceRisePct) {
        const extraPerYear = +((latest.amount - priorMedian) * chargesPerYear).toFixed(2);
        if (extraPerYear >= CONFIG.priceRiseFloorGbp) {
          findings.push({
            dedupe_key: `price_rise:${key}:${latest.amount.toFixed(2)}`,
            source: 'leak_radar',
            title: `${displayName} put its price up ${risePct.toFixed(0)}%`,
            detail: `Was about £${priorMedian.toFixed(2)}, now £${latest.amount.toFixed(2)} ${cycle.label}. `
                  + `That is £${extraPerYear.toFixed(2)} a year extra. `
                  + `Worth a cancel-or-haggle call.`,
            annual_value_gbp: extraPerYear,
            minutes_required: 15,
          });
        }
      }
    }
  }

  let trialAlreadyFlagged = false;

  // ================= FINDING: free trial converted =================
  // Classic pattern: a tiny authorisation charge, then the real price.
  const firstCharge = charges[0];
  if (firstCharge.amount <= CONFIG.trialProbeMaxGbp && typical > CONFIG.trialProbeMaxGbp * 3) {
    const daysSinceStart = Math.round((today - firstCharge.date) / DAY_MS);
    if (daysSinceStart <= 120 && annualCost >= CONFIG.annualValueFloorGbp) {
      trialAlreadyFlagged = true;
      findings.push({
        dedupe_key: `trial_converted:${key}`,
        source: 'leak_radar',
        title: `${displayName} free trial has turned into a paid subscription`,
        detail: `Started with a £${firstCharge.amount.toFixed(2)} charge, now billing `
              + `£${typical.toFixed(2)} ${cycle.label} — £${annualCost.toFixed(2)} a year. `
              + `Cancel now if you never actually started using it.`,
        annual_value_gbp: annualCost,
        minutes_required: 5,
      });
    }
  }

  // ================= FINDING: newly detected subscription =================
  // Only surface once, and only if it's worth real money.
  const isNew = Math.round((today - charges[0].date) / DAY_MS) <= (cycle.days * CONFIG.minOccurrences) + 30;
  // Suppressed when the trial alert already covered this merchant — two
  // messages about one subscription is exactly the noise that gets a
  // system muted.
  if (isNew && !trialAlreadyFlagged && annualCost >= CONFIG.annualValueFloorGbp) {
    findings.push({
      dedupe_key: `new_sub:${key}`,
      source: 'leak_radar',
      title: `New recurring payment: ${displayName} — £${annualCost.toFixed(2)}/year`,
      detail: `£${typical.toFixed(2)} ${cycle.label}, charged ${charges.length} times so far. `
            + `If this is one you meant to start, ignore this. If not, that is `
            + `£${annualCost.toFixed(2)} a year back.`,
      annual_value_gbp: annualCost,
      minutes_required: 5,
    });
  }
}

// Rank by annual value — the digest takes the top N off this pile.
findings.sort((a, b) => b.annual_value_gbp - a.annual_value_gbp);

return [{
  json: {
    subscriptions,
    findings,
    total_recurring_annual_gbp: +subscriptions
      .filter(s => s.status === 'active')
      .reduce((sum, s) => sum + s.annual_cost_gbp, 0)
      .toFixed(2),
  }
}];

// Turn detection output into idempotent SQL.
// Everything here is upsert-or-ignore: this workflow runs daily and must
// never create duplicate work items.
const data = $input.first().json;

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const statements = [];

// ---- subscriptions: full upsert, this table is a live mirror ----
for (const s of data.subscriptions || []) {
  statements.push(`INSERT INTO money.subscriptions
  (merchant_key, display_name, typical_amount_gbp, interval_days, occurrences,
   first_seen, last_charged, annual_cost_gbp, status, updated_at)
VALUES (${esc(s.merchant_key)}, ${esc(s.display_name)}, ${s.typical_amount_gbp},
        ${s.interval_days}, ${s.occurrences}, ${esc(s.first_seen)},
        ${esc(s.last_charged)}, ${s.annual_cost_gbp}, ${esc(s.status)}, now())
ON CONFLICT (merchant_key) DO UPDATE SET
  typical_amount_gbp = EXCLUDED.typical_amount_gbp,
  interval_days      = EXCLUDED.interval_days,
  occurrences        = EXCLUDED.occurrences,
  last_charged       = EXCLUDED.last_charged,
  annual_cost_gbp    = EXCLUDED.annual_cost_gbp,
  -- Never resurrect something the user has explicitly dealt with.
  status             = CASE
                         WHEN money.subscriptions.status IN ('cancelled_by_user','ignored')
                         THEN money.subscriptions.status
                         ELSE EXCLUDED.status
                       END,
  updated_at         = now();`);
}

// ---- findings: insert only if never seen before ----
// The unique dedupe_key is what stops the engine nagging you weekly about
// a subscription you already decided to keep.
for (const f of data.findings || []) {
  statements.push(`INSERT INTO money.actions
  (dedupe_key, source, title, detail, annual_value_gbp, minutes_required, status)
VALUES (${esc(f.dedupe_key)}, ${esc(f.source)}, ${esc(f.title)}, ${esc(f.detail)},
        ${f.annual_value_gbp}, ${f.minutes_required}, 'open')
ON CONFLICT (dedupe_key) DO NOTHING;`);
}

statements.push(`INSERT INTO money.sync_log (workflow, ok, rows_ingested, message)
VALUES ('02-leak-radar', true, ${(data.findings || []).length},
        ${esc(`tracking ${(data.subscriptions || []).length} recurring payments worth £${data.total_recurring_annual_gbp || 0}/yr`)});`);

return [{ json: { sql: statements.join('\n'), statement_count: statements.length } }];
